navigate_bounded.code:
def navigate_bounded(x,y,yaw_goal,seconds=5.0):
    start=state()['t']; reached=False; reason='timeout'
    while state()['t']-start<seconds:
        s=state(); p=s['pelvis_pos']; q=s['pelvis_quat']; pp=pos('person')
        yaw=math.atan2(2*(q[0]*q[3]+q[1]*q[2]),1-2*(q[2]*q[2]+q[3]*q[3]))
        if s['tilt_deg']>13 or p[2]<.68 or math.hypot(pp[0]-p[0],pp[1]-p[1])<.85:
            reason='safety_stop';break
        dx=x-p[0];dy=y-p[1];e=(yaw_goal-yaw+math.pi)%(2*math.pi)-math.pi
        ux=1.4*dx-.45*s['pelvis_linvel'][0];uy=1.4*dy-.45*s['pelvis_linvel'][1]
        vx=math.cos(yaw)*ux+math.sin(yaw)*uy;vy=-math.sin(yaw)*ux+math.cos(yaw)*uy
        walk(max(-.3,min(.3,vx)),max(-.22,min(.22,vy)),max(-.8,min(.8,1.8*e)))
        if math.hypot(dx,dy)<.035 and abs(e)<.07:
            reached=True;reason='reached';break
        wait(.05)
    walk(0,0,0)
    return {'reached':reached,'reason':reason,'pose':state()['pelvis_pos'],'tilt':state()['tilt_deg']}

