def start_current_xy_support_50hz(args):
    s = state()
    if s['tilt_deg'] > 8:
        return {'installed': False, 'reason': 'Entry tilt exceeds 8 degrees'}
    walk(0, 0, 0)
    p = state()['pelvis_pos']
    save('trial_new_goal', [p[0], p[1], args['yaw']])
    set_controller(trial_world_hold, hz=50)
    return controller_status()

