def compact_unloaded_elbow_up_pose(args):
    targets = {}
    for side, sign in [('left', 1.0), ('right', -1.0)]:
        targets[side + '_shoulder_pitch_joint'] = -2.4
        targets[side + '_shoulder_roll_joint'] = sign * 0.12
        targets[side + '_shoulder_yaw_joint'] = 0.0
        targets[side + '_elbow_joint'] = 0.15
        for axis in ['roll', 'pitch', 'yaw']:
            targets[side + '_wrist_' + axis + '_joint'] = 0.0
    move_joints(targets, 1.2)
    wait(0.4)
    return {'state': state(), 'left_elbow': pos('left_elbow_link'), 'right_elbow': pos('right_elbow_link'), 'left_palm': pos('left_palm'), 'right_palm': pos('right_palm')}
